def check_counterexample(K, N):
    targets = {2 * r % N for r in K}

    for p in K:
        for q in K:
            s = (p + q) % N
            if s not in targets:
                print(f"Failure found for pair ({p}, {q}). Sum: {s}. Targets: {sorted(list(targets))}")
                return True
    return False

K_candidate = [0, 1, 2, 4]
N = 2021
is_counterexample = check_counterexample(K_candidate, N)

if is_counterexample:
    print("K={0, 1, 2, 4} is a counterexample.")
else:
    print("K={0, 1, 2, 4} is NOT a counterexample.")

def check_condition(K, M=2021):
    # 1. Calculate the set R = {2r mod M | r in K}
    R = set()
    for r in K:
        R.add((2 * r) % M)

    # 2. Check if for every pair (p, q) in K, (p+q) mod M is in R
    for p in K:
        for q in K:
            sum_pq = (p + q) % M
            if sum_pq not in R:
                # print(f"Failed for pair ({p}, {q}). Sum = {sum_pq}. R = {R}")
                return False
    return True

# Construct the set K = {0, 1, ..., 1010}
M = 2021
K = set(range(1011))
size_K = len(K)

# Verify the condition
is_satisfied = check_condition(K, M)

print(f"Is condition satisfied? {is_satisfied}")
print(f"Size of K: {size_K}")
